package security

import (
	"reflect"
	"strings"
	"testing"
	"time"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/indicator"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// DEVDESK-145 step 2: column 0 of the :sec inventory is the activity column
// (Rule 125, "The activity column"). The blink phase is read at render.

const (
	indImage = "nexus/api:1.4"
	indRepo  = "/home/dev/workspaces/devdesk"
)

func inventoryLine(t *testing.T, m Model, name string) string {
	t.Helper()
	short := name
	if i := strings.LastIndex(name, "/"); i >= 0 {
		short = name[i+1:]
	}
	for _, l := range strings.Split(m.View(), "\n") {
		if strings.Contains(l, short) {
			return l
		}
	}
	t.Fatalf("no rendered line holds %q:\n%s", short, m.View())
	return ""
}

func rowByName(t *testing.T, m Model, name string) scanTarget {
	t.Helper()
	for _, r := range m.inventory.Items() {
		if r.Name == name {
			return r
		}
	}
	t.Fatalf("no row named %q", name)
	return scanTarget{}
}

func col0(t *testing.T) datatable.Column[scanTarget] {
	t.Helper()
	c := inventoryColumns(false, false)[0]
	if c.Indicator == nil {
		t.Fatal("column 0 has no Indicator")
	}
	return c
}

func TestColumnZeroIsTheActivityColumn(t *testing.T) {
	for _, tc := range []struct{ ci, cfg bool }{{false, false}, {true, false}, {false, true}, {true, true}} {
		c := inventoryColumns(tc.ci, tc.cfg)[0]
		if c.Title != "" {
			t.Errorf("ci=%v cfg=%v: column 0 titled %q, want untitled", tc.ci, tc.cfg, c.Title)
		}
		if c.Sizing != datatable.SizingFixed || c.MinWidth != datatable.IconColumnWidth {
			t.Errorf("column 0 sizing/min = %v/%d, want SizingFixed/%d", c.Sizing, c.MinWidth, datatable.IconColumnWidth)
		}
		if c.Indicator == nil {
			t.Errorf("ci=%v cfg=%v: column 0 is not built by datatable.IndicatorColumn", tc.ci, tc.cfg)
		}
		if c.Less != nil || c.Search != nil {
			t.Errorf("column 0 declares Less=%v Search=%v, want neither", c.Less != nil, c.Search != nil)
		}
	}
	m := inventoryModel(t, inventoryFixtures()...)
	if shapes := m.inventory.Shapes(); len(shapes) == 0 || !shapes[0].Indicator {
		t.Errorf("the live inventory has no activity column 0: %+v", shapes)
	}
}

func TestTheViewExposesItsTableToTheActivityGuard(t *testing.T) {
	m := inventoryModel(t, inventoryFixtures()...)
	av, ok := any(m).(interface {
		ActivityTables() map[string]datatable.ActivityTable
	})
	if !ok {
		t.Fatal("Model does not expose ActivityTables()")
	}
	tables := av.ActivityTables()
	tbl, ok := tables["sec/inventory"]
	if !ok || len(tables) != 1 {
		t.Fatalf("ActivityTables() keys = %v, want exactly [sec/inventory]", tables)
	}
	if shapes := tbl.Shapes(); len(shapes) == 0 || !shapes[0].Indicator {
		t.Errorf("the reported table has no activity column 0: %+v", shapes)
	}
}

func TestEachActivityStateRendersItsGlyphOnItsRow(t *testing.T) {
	queued := secRun(jobs.KindScan, secCtx, jobs.ItemQueued, indRepo)
	running := secRun(jobs.KindScan, secCtx, jobs.ItemRunning, indRepo)
	failure := secFailure(jobs.KindScan, secCtx, indRepo, time.Now())
	tests := []struct {
		name  string
		runs  []jobs.Run
		fails []jobs.Failure
		blink bool
		state indicator.State
	}{
		{"running, phase on", []jobs.Run{running}, nil, true, indicator.Running},
		{"running, phase off", []jobs.Run{running}, nil, false, indicator.Running},
		{"queued, phase on", []jobs.Run{queued}, nil, true, indicator.Queued},
		{"queued, phase off", []jobs.Run{queued}, nil, false, indicator.Queued},
		{"failed, phase on", nil, []jobs.Failure{failure}, true, indicator.Failed},
		{"failed, phase off", nil, []jobs.Failure{failure}, false, indicator.Failed},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			m := inventoryModel(t, inventoryFixtures()...)
			m = feed(t, m,
				jobs.ChangedMsg{Runs: tc.runs, Failures: tc.fails, Context: secCtx},
				jobs.FrameMsg{Blink: tc.blink})
			line := inventoryLine(t, m, indRepo)
			want := indicator.Glyph(tc.state, tc.blink)
			if !strings.Contains(line, want) {
				t.Errorf("row lacks %q:\n%s", want, line)
			}
			if strings.Contains(line, theme.IconWorkspace) {
				t.Errorf("the glyph shares the row with the resting icon:\n%s", line)
			}
			if other := inventoryLine(t, m, indImage); hasAnyGlyph(other) {
				t.Errorf("an untouched row shows an activity glyph:\n%s", other)
			}
		})
	}
}

func hasAnyGlyph(line string) bool {
	for _, s := range indicator.States() {
		if g := indicator.Glyph(s, true); g != "" && strings.Contains(line, g) {
			return true
		}
	}
	return strings.Contains(line, indicator.Glyph(indicator.Running, false))
}

func TestAnIdleRowShowsItsKindIconNeverGreen(t *testing.T) {
	m := inventoryModel(t, inventoryFixtures()...)
	col := col0(t)
	for name, icon := range map[string]string{indRepo: theme.IconWorkspace, indImage: theme.IconDocker} {
		r := rowByName(t, m, name)
		if got := col.Indicator(r); got != indicator.Idle {
			t.Errorf("%s: Indicator = %v, want Idle", name, got)
		}
		if got := col.Cell(r); got != icon {
			t.Errorf("%s: resting cell = %q, want %q", name, got, icon)
		}
		if got, want := col.Style(r).GetForeground(), theme.IconStyle(r.kindIconRole()).GetForeground(); got != want {
			t.Errorf("%s: resting style = %v, want the IconStyle role %v", name, got, want)
		}
		if col.Style(r).GetForeground() == theme.StatusOKStyle.GetForeground() {
			t.Errorf("%s: an idle icon is green", name)
		}
	}
}

func TestADoneItemGoesBackToItsIcon(t *testing.T) {
	m := inventoryModel(t, inventoryFixtures()...)
	m = withJobs(t, m, secRun(jobs.KindScan, secCtx, jobs.ItemDone, indRepo))
	if got := col0(t).Indicator(rowByName(t, m, indRepo)); got != indicator.Idle {
		t.Errorf("a finished row: Indicator = %v, want Idle", got)
	}
	if line := inventoryLine(t, m, indRepo); hasAnyGlyph(line) {
		t.Errorf("a finished row shows an activity glyph:\n%s", line)
	}
}

func TestAQueuedRowBlinksNotAndKeepsItsPreviousScannedCell(t *testing.T) {
	m := inventoryModel(t, inventoryFixtures()...)
	m = feed(t, m,
		jobs.ChangedMsg{Runs: []jobs.Run{secRun(jobs.KindScan, secCtx, jobs.ItemQueued, indRepo)}, Context: secCtx},
		jobs.FrameMsg{Blink: true})
	r := rowByName(t, m, indRepo)
	if r.ScanRunning {
		t.Error("a queued scan holds the Scanned cell")
	}
	if got, want := inventoryScannedCell(r), theme.TimeAgo(r.ScannedAt); got != want {
		t.Errorf("queued Scanned cell = %q, want the previous %q", got, want)
	}
}

func TestARunningScanHoldsTheScannedCellDim(t *testing.T) {
	m := inventoryModel(t, inventoryFixtures()...)
	m = feed(t, m, jobs.ChangedMsg{
		Runs: []jobs.Run{secRun(jobs.KindScan, secCtx, jobs.ItemRunning, indRepo)}, Context: secCtx})
	r := rowByName(t, m, indRepo)
	if got := inventoryScannedCell(r); got != scanningText {
		t.Errorf("Scanned cell = %q, want %q", got, scanningText)
	}
package explorer

import (
	"strings"
	"testing"

	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/components"
)

// ── DEVDESK-139: the frame arrives in its own message ────────────────────────

// The tree: a working row takes its frame from FrameMsg.
func TestAFrameMovesTheRowSpinner(t *testing.T) {
	m := loadedModel(t)
	m, _ = step(t, m, components.CreationFormSubmitMsg{FormType: components.FormTypeGroup, Name: "new"})
	m = feed(t, m, jobs.ChangedMsg{Runs: []jobs.Run{createRun("new", "new")}})

	for _, frame := range []string{"X", "Y"} {
		m = feed(t, m, jobs.FrameMsg{Frame: frame})
		row, ok := rowFor(m, "new")
		if !ok {
			t.Fatal("the placeholder row is gone")
		}
		if got := iconCell(row); got != frame {
			t.Errorf("icon cell = %q after frame %q, want the spinner", got, frame)
		}
	}
	if len(m.jobs) != 1 {
		t.Errorf("the held runs = %d after a frame, want the 1 from the snapshot", len(m.jobs))
	}
}

// The clone list: a running row takes its frame from FrameMsg.
func TestAFrameMovesTheCloneListSpinner(t *testing.T) {
	h := cloning(t)
	h.emit(found("alpha/api"), began("alpha/api"))

	for _, frame := range []string{"X", "Y"} {
		h.m = feed(t, h.m, jobs.FrameMsg{Frame: frame})
		rows := h.m.clone.table.Table().Rows()
		if len(rows) != 1 {
			t.Fatalf("rows = %v, want the one repository", rows)
		}
		if got := rows[0][colCloneStatus]; !strings.HasPrefix(got, frame+" cloning") {
			t.Errorf("status cell = %q after frame %q, want the new frame", got, frame)
		}
	}
	if got := h.item(0).State; got != jobs.ItemRunning {
		t.Errorf("state = %v, a frame must not touch the run", got)
	}
}

func TestAFrameMovesTheFooterSpinner(t *testing.T) {
	m := loadedModel(t)
	m.loading = true // the tree is reloading: the footer shows a spinner line

	m = feed(t, m, jobs.FrameMsg{RenderedFrame: "<R1>"})

	if footer := m.RenderFooter(160); !strings.Contains(footer, "<R1>") {
		t.Errorf("the footer does not carry the new frame:\n%s", footer)
	}
}
	node, ok := m.selectedNode()
	if !ok || node.FullPath != "alpha/svc" || node.Creating {
		t.Errorf("selected node = %+v, want the settled project", node)
	}
	if m.loading {
		t.Error("a template failure triggered a refresh")
	}
	if m.footer.Level() != components.LevelWarning {
		t.Errorf("footer level = %v, want a warning", m.footer.Level())
	}
	if !strings.Contains(m.footer.Text(), "template") {
		t.Errorf("footer = %q, want it to name the template", m.footer.Text())
	}
}

// The spinner on a working row comes from the broadcast, not from this view's
// own chain — that one stops when the tree settles, so a frame taken from it
// would freeze on frame zero for the whole of the call.
func TestAWorkingRowTakesItsFrameFromTheBroadcast(t *testing.T) {
	m := loadedModel(t)
	m, _ = step(t, m, components.CreationFormSubmitMsg{FormType: components.FormTypeGroup, Name: "new"})

	m = feed(t, m, jobs.ChangedMsg{
		Runs: []jobs.Run{createRun("new", "new")},
	})
	m = feed(t, m, jobs.FrameMsg{Frame: "⣾"})

	row, ok := rowFor(m, "new")
	if !ok {
		t.Fatal("the placeholder row is gone")
	}
	if row.frame != "⣾" {
		t.Errorf("row frame = %q, want the broadcast's", row.frame)
	}
	if got := iconCell(row); got != "⣾" {
		t.Errorf("icon cell = %q, want the spinner", got)
	}
}

// A reload replaces the level wholesale, and a create in flight has nothing yet
// to be replaced by. Dropped, its row would vanish mid-request while the
// registry went on tracking the run.
func TestARefreshKeepsACreationInFlightOnScreen(t *testing.T) {
	m := loadedModel(t)
	m, _ = step(t, m, components.CreationFormSubmitMsg{FormType: components.FormTypeGroup, Name: "new"})

	m, _ = step(t, m, testutil.Key("ctrl+r"))
	if _, ok := rowFor(m, "new"); !ok {
		t.Fatal("ctrl+r took the in-flight row off screen")
	}

	m = feed(t, m, RootGroupsLoadedMsg{Nodes: rootFixtures()})
	if _, ok := rowFor(m, "new"); !ok {
		t.Fatal("the reload dropped the in-flight row")
	}

	// And it still settles onto the row the refresh carried over.
	m = feed(t, m, GroupCreatedMsg{Namespace: newGroup(7, "alpha/new"), Target: "new"})
	if _, ok := rowFor(m, "new"); ok {
		t.Error("the placeholder outlived the answer")
	}
	help := m.GetHelpContent()
	if !strings.Contains(help.Description, "organizations") {
		t.Errorf("the help still describes groups rather than organizations: %q", help.Description)
	}
	if strings.Contains(help.Title, "GitLab") {
		t.Errorf("the help title still names GitLab: %q", help.Title)
	}
}

// ── §3.56 : the icon columns ─────────────────────────────────────────────────

// The first column carries the kind, and the two kinds are two glyphs.
func TestTheFirstColumnSaysWhatTheRowIs(t *testing.T) {
	group := explorerRow{node: &TreeNode{Type: NodeTypeGroup}}
	project := explorerRow{node: &TreeNode{Type: NodeTypeProject}}

	if got := iconCell(group); got != theme.IconNamespace {
		t.Errorf("iconCell(group) = %q, want the namespace glyph", got)
	}
	if got := iconCell(project); got != theme.IconRepository {
		t.Errorf("iconCell(project) = %q, want the repository glyph", got)
	}
}

// None of the explorer's glyphs is one the workspaces view uses. The two lists
// answer different questions — what the forge holds, what is on disk — and a
// row that looked the same in both would claim they are the same object.
func TestTheExplorerGlyphsAreNotTheWorkspaceOnes(t *testing.T) {
	ws := []string{theme.IconGitBranch, theme.IconDirectory, theme.IconDirectoryOpen, theme.IconFile}
	for _, mine := range []string{theme.IconNamespace, theme.IconRepository} {
		for _, theirs := range ws {
			if mine == theirs {
				t.Errorf("the explorer and workspaces share the glyph %q", mine)
			}
		}
	}
}

// In the clone selection the glyph becomes a checkbox — Rule 125 fixes the
// column at two cells, so the two cannot sit side by side.
func TestTheSelectionReplacesTheGlyphWithACheckbox(t *testing.T) {
	row := explorerRow{node: &TreeNode{Type: NodeTypeProject}, selecting: true, check: theme.CheckAll}

	if got := iconCell(row); got != theme.IconChecked {
		t.Errorf("iconCell(ticked) = %q, want the ticked box", got)
	}
}

// …and the colour still says which kind it is, which is what makes sharing the
// column honest rather than lossy.
func TestTheKindSurvivesTheSelectionAsAColour(t *testing.T) {
	group := explorerRow{node: &TreeNode{Type: NodeTypeGroup}, selecting: true}
	project := explorerRow{node: &TreeNode{Type: NodeTypeProject}, selecting: true}

	if iconCell(group) != iconCell(project) {
		t.Fatal("the two kinds show different boxes — this test is about the colour")
	}
	if iconStyle(group).GetForeground() == iconStyle(project).GetForeground() {
		t.Error("a ticked group and a ticked project are the same colour — the kind is lost")
	}
}

// Rule 122: what a Cell returns is measured, so it must carry no escape.
func TestTheIconCellsCarryNoEscapeSequence(t *testing.T) {
	rows := []explorerRow{
		{node: &TreeNode{Type: NodeTypeGroup, Visibility: "public"}},
		{node: &TreeNode{Type: NodeTypeProject, Visibility: "private"}, selecting: true, check: theme.CheckSome},
	}
	for _, row := range rows {
		if strings.Contains(iconCell(row), "\x1b") {
			t.Errorf("iconCell carries an escape sequence: %q", iconCell(row))
		}
		if strings.Contains(visibilityIcon(row.node), "\x1b") {
			t.Errorf("visibilityIcon carries an escape sequence: %q", visibilityIcon(row.node))
		}
	}
}

// The three visibilities are three glyphs, and anything else is an empty cell —
// a placeholder would be a wrong answer where nothing is a true one.
func TestVisibilityIsAGlyphOrNothing(t *testing.T) {
		{"real node: delete only (H1)", &TreeNode{FullPath: "alpha/api"}, []jobs.Kind{jobs.KindDelete}},
		{"placeholder: delete and create", &TreeNode{FullPath: "alpha/new", Creating: true}, []jobs.Kind{jobs.KindDelete, jobs.KindCreate}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := rowKinds(tt.node)
			if len(got) != len(tt.want) {
				t.Fatalf("rowKinds = %v, want %v", got, tt.want)
			}
			for _, k := range tt.want {
				found := false
				for _, g := range got {
					found = found || g == k
				}
				if !found {
					t.Errorf("rowKinds = %v, missing %v", got, k)
				}
			}
		})
	}
}

func TestRowActivity(t *testing.T) {
	real := &TreeNode{FullPath: "alpha/api"}
	placeholder := &TreeNode{FullPath: "alpha/new", Creating: true}
	realNew := &TreeNode{FullPath: "alpha/new"}

	tests := []struct {
		name     string
		node     *TreeNode
		runs     []jobs.Run
		failures []jobs.Failure
		state    indicator.State
		want     string // Detail.String(); "" = zero detail
	}{
		{"running delete", real, actRunning(t, jobs.KindDelete, actCtx, "alpha/api"), nil,
			indicator.Running, "● Deleting alpha/api"},
		{"running create on a placeholder", placeholder, actRunning(t, jobs.KindCreate, actCtx, "alpha/new"), nil,
			indicator.Running, "● Creating alpha/new"},
		{"running create on a real node (H1)", realNew, actRunning(t, jobs.KindCreate, actCtx, "alpha/new"), nil,
			indicator.Idle, ""},

